static uint32_t s_ota_offset = 0;
static size_t s_expected_ota_size = 0;

void *glue_ota_begin_firmware_update(char *file_name, size_t total_size) {
  if (total_size > ota_get_max_fw_size()) {
      MG_ERROR(("Firmware size %lu > partition %lu", total_size, (unsigned long)ota_get_max_fw_size()));
      return NULL;
  }
  s_ota_offset = 0;
  s_expected_ota_size = total_size;
  bool ok = (ota_begin((uint32_t) total_size, 0U) == 0);
  MG_DEBUG(("%s size %lu, ok: %d", file_name, total_size, ok));
  return ok ? (void *) 1 : NULL;
}

static void delayed_ota_commit(void *arg) {
  (void)arg;
      (void) ota_finalize(NULL);
      (void) ota_commit();
}

bool glue_ota_end_firmware_update(void *context) {
  if (s_ota_offset == s_expected_ota_size && s_expected_ota_size > 0) {
      MG_INFO(("OTA fully received (%lu bytes). Scheduling commit.", s_ota_offset));
      mg_timer_add(&g_mgr, 500, 0, delayed_ota_commit, context);
  } else {
      MG_ERROR(("OTA aborted/incomplete (received %lu of %lu). Cancelling update.", s_ota_offset, (unsigned long)s_expected_ota_size));
      // Optionally call ota_abort() here if we implemented it, or let next ota_begin() handle it.
  }
  s_expected_ota_size = 0;
  s_ota_offset = 0;
  return true;
}

void glue_ota_abort_firmware_update(void) {
  ota_abort();
  s_ota_offset = 0;
  s_expected_ota_size = 0;
}

bool glue_ota_write_firmware_update(void *context, void *buf, size_t len) {
  MG_DEBUG(("ctx: %p %p/%lu", context, buf, len));
  int ret = ota_write_chunk(s_ota_offset, (const uint8_t *)buf, len);
  if (ret == 0) {
      s_ota_offset += len;
      return true;
  }
  return false;
}

void *glue_upload_open_file_upload(char *file_name, size_t total_size) {
  char path[128], *p = NULL;
  FILE *fp = NULL;
  if ((p = strrchr(file_name, '/')) == NULL) p = file_name;
  mg_snprintf(path, sizeof(path), "/tmp/%s", p);
#if MG_ENABLE_POSIX_FS
  fp = fopen(path, "w+b");
#endif
  MG_DEBUG(("opening [%s] size %lu, fp %p", path, total_size, fp));
  return fp;
}
bool glue_upload_close_file_upload(void *fp) {
  MG_DEBUG(("closing %p", fp));
#if MG_ENABLE_POSIX_FS
  return fclose((FILE *) fp) == 0;
#else
  return false;
#endif
}
bool glue_upload_write_file_upload(void *fp, void *buf, size_t len) {
  MG_DEBUG(("writing fp %p %p %lu bytes", fp, buf, len));
#if MG_ENABLE_POSIX_FS
  return fwrite(buf, 1, len, (FILE *) fp) == len;
#else
  return false;
#endif
}
#include "board.h"
#include "sntp_app.h"
#include "app.h"
// upload_percent is driven by XHR progress events in the browser; no C-side variable needed
static uint32_t s_upload_percent = 0;
static struct state s_state = {.error = false, .wifi = false, .ethernet = true, .upload_percent = 0, .time = "1767674883", .temperature = 27, .uptime = 0, .version = BSP_SW_VERSION_STR, .online = false, .lights = false};
void glue_get_state(struct state *data) {
  static uint32_t time_sync = 0;
  time_sync ++;
  if (time_sync % 10 == 0)
  {
    uint32_t time = sntp_get_timestamp();
    s_state.uptime = gateway.uptime;
    s_state.devices = get_num_dev_online();
    s_state.cpu = app_get_cpu_usage();
    s_state.ram = app_get_ram_usage();
    s_state.total_ram = (configTOTAL_HEAP_SIZE / 1024);
    s_state.free_ram = s_state.total_ram - s_state.ram;
    s_state.total_flash = 16*1024;
    s_state.flash = 1*1024;
    s_state.free_flash = s_state.total_flash - s_state.flash;
    s_state.online = mqtt_client_is_connected(&gateway.thingsboard.base);
    s_state.temperature = bsp_get_temp();
    strcpy(s_state.version, BSP_SW_VERSION_STR);
    sprintf(s_state.time, "%lu", time);
  }
  s_state.upload_percent = s_upload_percent;
  s_state.lights = true;
  s_state.error = false;
  s_state.wifi = false;
  s_state.ethernet = true;
  *data = s_state;  // Sync with your device
}

